import { chromium, devices } from "/home/mvhenten/development/stallion-worktrees/rich-palette/node_modules/playwright/index.mjs";
import { accessHeaders } from "/home/mvhenten/development/stallion-worktrees/rich-palette/npm-scripts/env.mjs";
const origin = process.argv[2];
const dir = "/home/mvhenten/development/.tmp/stallion-palette";
const id = (() => { const b = crypto.getRandomValues(new Uint8Array(16)); let v = 0n; for (const x of b) v = (v << 8n) | BigInt(x); return v.toString(36).padStart(25, "0"); })();
const url = `${origin}/b/${id}`;
const targets = {
  phone: { ...devices["iPhone 14"] },
  tablet: { ...devices["Galaxy Tab S9"] },
  desktop: { viewport: { width: 1440, height: 900 } },
};
const errors = [];
const browser = await chromium.launch({ headless: true });
const open = async (opts, scheme, mode) => {
  const context = await browser.newContext({ ...opts, colorScheme: scheme, extraHTTPHeaders: accessHeaders() });
  if (mode) await context.addInitScript((m) => localStorage.setItem("stallion:toolbar-mode", m), mode);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && errors.push(`${m.text()} @ ${m.location().url}`));
  page.on("pageerror", (e) => errors.push(e.message));
  await page.goto(url, { waitUntil: "load" });
  await page.locator("canvas.surface").waitFor({ state: "visible" });
  await page.waitForTimeout(1200);
  return { context, page };
};
const leader = await open(targets.desktop, "light", "Quick");
for (const [name, opts] of Object.entries(targets)) {
  for (const scheme of ["light", "dark"]) {
    const { context, page } = await open(opts, scheme, "Palette");
    const pal = page.locator('.toolbar[data-layout="Palette"]');
    if (!(await pal.isVisible())) errors.push(`${name} ${scheme}: palette not open`);
    const box = await pal.boundingBox();
    const floater = await page.locator(".presence-floater").boundingBox();
    const vp = page.viewportSize();
    console.log(name, scheme, "palette", JSON.stringify(box), "floater", JSON.stringify(floater), "vp", JSON.stringify(vp));
    await page.screenshot({ path: `${dir}/${name}-${scheme}-palette.png` });
    await context.close();
  }
}
for (const mode of ["Quick", "Palette"]) {
  const { context, page } = await open(targets.phone, "light", mode);
  const chip = page.locator(".presence-floater .peer:not([disabled])").first();
  await chip.waitFor({ state: "visible", timeout: 10000 });
  await chip.click();
  const pill = page.locator(".follow-pill");
  await pill.waitFor({ state: "visible", timeout: 5000 });
  console.log(mode, "pill:", (await pill.innerText()).trim());
  await page.screenshot({ path: `${dir}/phone-follow-${mode.toLowerCase()}.png` });
  await context.close();
}
{
  const { context, page } = await open(targets.phone, "light", "Quick");
  await page.getByRole("button", { name: "More tools" }).click();
  await page.screenshot({ path: `${dir}/phone-light-quick-expanded.png` });
  await context.close();
}
await leader.context.close();
await browser.close();
console.log("console errors:", errors.length ? errors : "none");
EOF
